// Shared navbar for study-note pages. Generated by tools/build_nav.py — edit tools/nav.template.js, not nav.js.
(function () {
  const DATA = /*__DATA__*/null;
  if (!DATA || window.__studyNav) return;
  window.__studyNav = true;

  const script = document.currentScript;
  const base = new URL(".", script ? script.src : location.href);
  const here = decodeURIComponent(location.pathname);
  const idx = DATA.pages.findIndex((p) => here.endsWith("/" + p.path));
  const cur = DATA.pages[idx];
  const prev = idx > 0 ? DATA.pages[idx - 1] : null;
  const next = idx >= 0 && idx < DATA.pages.length - 1 ? DATA.pages[idx + 1] : null;
  const href = (p) => new URL(p.path, base).href;
  const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
  const secShort = (s) => (DATA.sections[s] || "Section " + s).replace(/\s*-?\s*\d+%\s*$/, "");

  const host = document.createElement("div");
  host.id = "study-nav";
  host.style.cssText = "all:initial;display:block;position:relative;z-index:2147483000";
  const root = host.attachShadow({ mode: "open" });

  // Group pages by section, then kind.
  let list = "";
  let lastSec = null, lastKind = null;
  for (const p of DATA.pages) {
    if (p.section !== lastSec) {
      if (lastSec !== null) list += "</ul></section>";
      list += `<section><h2>${esc(p.section)}. ${esc(secShort(p.section))}</h2><ul>`;
      lastSec = p.section; lastKind = null;
    }
    if (p.kind !== lastKind) {
      list += `<li class="kind">${esc(DATA.kinds[p.kind] || p.kind)}</li>`;
      lastKind = p.kind;
    }
    const on = p === cur ? ' aria-current="page"' : "";
    list += `<li><a href="${href(p)}"${on}><span class="code">${esc(p.code)}</span><span>${esc(p.title)}</span></a></li>`;
  }
  if (lastSec !== null) list += "</ul></section>";

  const arrow = (p, dir) => p
    ? `<a class="step" href="${href(p)}" title="${esc(p.section + "." + p.code + " — " + p.title)}">${dir < 0 ? "‹ Prev" : "Next ›"}</a>`
    : `<span class="step off">${dir < 0 ? "‹ Prev" : "Next ›"}</span>`;

  root.innerHTML = `
<style>
  :host { --bg:#ffffff; --fg:#1f2328; --muted:#656d76; --line:#d0d7de; --hover:#f3f4f6; --accent:#0969da; --accent-bg:#ddf4ff; }
  @media (prefers-color-scheme: dark) {
    :host { --bg:#161b22; --fg:#e6edf3; --muted:#8d96a0; --line:#30363d; --hover:#21262d; --accent:#4493f8; --accent-bg:#1f2d3d; }
  }
  * { box-sizing:border-box; }
  nav { font:14px/1.4 system-ui,-apple-system,"Segoe UI",Roboto,sans-serif; color:var(--fg); background:var(--bg);
        border-bottom:1px solid var(--line); padding:8px 16px; display:flex; flex-wrap:wrap; align-items:center; gap:8px 12px; }
  a { color:inherit; text-decoration:none; }
  .home { font-weight:600; padding:4px 8px; border-radius:6px; }
  .home:hover, .step:hover, button:hover { background:var(--hover); }
  .crumb { color:var(--muted); min-width:0; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; flex:1 1 200px; }
  .crumb b { color:var(--fg); font-weight:600; }
  .actions { display:flex; gap:4px; margin-left:auto; }
  .step, button { font:inherit; color:inherit; background:none; border:1px solid var(--line); border-radius:6px; padding:4px 10px; cursor:pointer; white-space:nowrap; }
  .step.off { opacity:.4; cursor:default; }
  .panel { display:none; position:absolute; left:0; right:0; top:100%; max-height:min(70vh,640px); overflow:auto;
           background:var(--bg); border-bottom:1px solid var(--line); box-shadow:0 8px 24px rgba(0,0,0,.18); padding:8px 16px 16px;
           font:14px/1.4 system-ui,-apple-system,"Segoe UI",Roboto,sans-serif; color:var(--fg); }
  .panel.open { display:grid; grid-template-columns:repeat(auto-fit,minmax(min(100%,360px),1fr)); gap:0 32px; }
  h2 { font-size:13px; text-transform:uppercase; letter-spacing:.04em; color:var(--muted); margin:12px 0 4px; }
  ul { list-style:none; margin:0; padding:0; }
  li.kind { font-size:12px; color:var(--muted); margin:8px 0 2px; }
  li a { display:flex; gap:8px; padding:4px 6px; border-radius:6px; }
  li a:hover { background:var(--hover); }
  li a[aria-current] { background:var(--accent-bg); color:var(--accent); font-weight:600; }
  .code { flex:0 0 3.2em; color:var(--muted); font-variant-numeric:tabular-nums; }
  a:focus-visible, button:focus-visible { outline:2px solid var(--accent); outline-offset:1px; }
</style>
<nav aria-label="Study notes">
  <a class="home" href="${base.href}">⌂ NCP-ARI Notes</a>
  <span class="crumb">${cur ? `${esc(cur.section)}. ${esc(secShort(cur.section))} · <b>${esc(cur.code)}</b> · ${esc(cur.title)}` : ""}</span>
  <span class="actions">${arrow(prev, -1)}${arrow(next, 1)}<button type="button" aria-expanded="false" aria-controls="panel">All notes ▾</button></span>
</nav>
<div class="panel" id="panel">${list}</div>`;

  const btn = root.querySelector("button");
  const panel = root.getElementById("panel");
  const toggle = (open) => {
    panel.classList.toggle("open", open);
    btn.setAttribute("aria-expanded", String(open));
    const a = open && root.querySelector("[aria-current]");
    if (a) panel.scrollTop = a.offsetTop - panel.clientHeight / 2;
  };
  btn.addEventListener("click", (e) => { e.stopPropagation(); toggle(!panel.classList.contains("open")); });
  document.addEventListener("click", (e) => { if (!e.composedPath().includes(host)) toggle(false); });
  document.addEventListener("keydown", (e) => { if (e.key === "Escape") toggle(false); });

  document.body.prepend(host);
})();
